-- ========================================
-- CSMS FULL DATABASE SETUP WITH DATA
-- ========================================
-- Purpose:
-- Recreate the CSMS schema and insert the current sample data used by the app.
--
-- Run from SQL*Plus after connecting as the CSMS user:
-- @database/csms_full_setup_with_data.sql
--
-- Current object inventory:
-- Tables: 22
-- Views: none
-- Triggers: 2
-- Sequences: 13
-- Indexes: generated by primary key and unique constraints.
-- ========================================

SET DEFINE OFF;
ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD';

-- ========================================
-- DROP TABLES FOR RE-RUN
-- ========================================

BEGIN
    FOR t IN (SELECT table_name FROM user_tables WHERE table_name IN (
        'ASSIGNMENTS','ATTENDANCE','CLASSES','CLASS_SUBJECT_TEACHER',
        'COMMUNICATION','COMMUNICATION_READ_STATE','COUNSELLING','LOGIN_AUDIT','MARKS','PARENT_STUDENT',
        'APP_SETTINGS','QUESTION_BANK','QUESTION_PAPERS','ROLES','STUDENTS','STUDENT_CLASS',
        'SCHOOL_PROFILE_IMAGES','SUBJECTS','SUBMISSIONS','TEACHERS','USER_PROFILE_IMAGES','USERS'
    )) LOOP
        EXECUTE IMMEDIATE 'DROP TABLE ' || t.table_name || ' CASCADE CONSTRAINTS PURGE';
    END LOOP;
END;
/

PURGE RECYCLEBIN;

BEGIN
    FOR s IN (SELECT sequence_name FROM user_sequences WHERE sequence_name IN (
        'SEQ_ASSIGNMENTS','SEQ_ATTENDANCE','SEQ_CLASSES','SEQ_COMMUNICATION',
        'SEQ_COUNSELLING','SEQ_LOGIN_AUDIT','SEQ_MARKS','SEQ_QUESTION_BANK','SEQ_QUESTION_PAPERS',
        'SEQ_STUDENTS','SEQ_SUBMISSIONS','SEQ_TEACHERS','SEQ_USERS'
    )) LOOP
        EXECUTE IMMEDIATE 'DROP SEQUENCE ' || s.sequence_name;
    END LOOP;
END;
/

-- ========================================
-- CREATE TABLES
-- ========================================

CREATE TABLE ROLES (
    ROLE_ID NUMBER PRIMARY KEY,
    ROLE_NAME VARCHAR2(20) UNIQUE NOT NULL
);

CREATE TABLE USERS (
    USER_ID NUMBER PRIMARY KEY,
    NAME VARCHAR2(100) NOT NULL,
    EMAIL VARCHAR2(100) UNIQUE NOT NULL,
    PASSWORD_HASH VARCHAR2(255) NOT NULL,
    ROLE_ID NUMBER NOT NULL,
    PHONE VARCHAR2(15),
    CREATED_AT DATE DEFAULT SYSDATE,
    IS_ACTIVE NUMBER(1) DEFAULT 1 NOT NULL,
    CONSTRAINT CHK_USERS_IS_ACTIVE CHECK (IS_ACTIVE IN (0, 1)),
    CONSTRAINT FK_USERS_ROLE FOREIGN KEY (ROLE_ID)
        REFERENCES ROLES(ROLE_ID)
);

CREATE TABLE CLASSES (
    CLASS_ID NUMBER PRIMARY KEY,
    CLASS_NAME VARCHAR2(20) NOT NULL,
    SECTION VARCHAR2(5) NOT NULL,
    ACADEMIC_YEAR VARCHAR2(10) NOT NULL,
    CONSTRAINT UQ_CLASS UNIQUE (CLASS_NAME, SECTION, ACADEMIC_YEAR)
);

CREATE TABLE SUBJECTS (
    SUBJECT_ID NUMBER PRIMARY KEY,
    SUBJECT_NAME VARCHAR2(100) UNIQUE NOT NULL
);

CREATE TABLE TEACHERS (
    TEACHER_ID NUMBER PRIMARY KEY,
    USER_ID NUMBER UNIQUE,
    QUALIFICATION VARCHAR2(100),
    EXPERIENCE NUMBER CHECK (EXPERIENCE >= 0),
    CONSTRAINT FK_TEACHER_USER FOREIGN KEY (USER_ID)
        REFERENCES USERS(USER_ID)
);

CREATE TABLE STUDENTS (
    STUDENT_ID NUMBER PRIMARY KEY,
    USER_ID NUMBER UNIQUE NOT NULL,
    DOB DATE NOT NULL,
    GENDER VARCHAR2(10),
    CONDUCT VARCHAR2(20),
    CONDUCT_REMARKS VARCHAR2(200),
    CONSTRAINT CHK_GENDER CHECK (GENDER IN ('Male','Female','Other')),
    CONSTRAINT CHK_CONDUCT CHECK (CONDUCT IN ('Excellent','Good','Average','Poor')),
    CONSTRAINT FK_STUDENT_USER FOREIGN KEY (USER_ID)
        REFERENCES USERS(USER_ID)
);

CREATE TABLE CLASS_SUBJECT_TEACHER (
    CLASS_ID NUMBER,
    SUBJECT_ID NUMBER,
    TEACHER_ID NUMBER,
    PRIMARY KEY (CLASS_ID, SUBJECT_ID, TEACHER_ID),
    CONSTRAINT FK_CST_CLASS FOREIGN KEY (CLASS_ID) REFERENCES CLASSES(CLASS_ID),
    CONSTRAINT FK_CST_SUBJECT FOREIGN KEY (SUBJECT_ID) REFERENCES SUBJECTS(SUBJECT_ID),
    CONSTRAINT FK_CST_TEACHER FOREIGN KEY (TEACHER_ID) REFERENCES TEACHERS(TEACHER_ID)
);

CREATE TABLE STUDENT_CLASS (
    STUDENT_ID NUMBER,
    CLASS_ID NUMBER,
    PRIMARY KEY (STUDENT_ID, CLASS_ID),
    CONSTRAINT FK_SC_STUDENT FOREIGN KEY (STUDENT_ID) REFERENCES STUDENTS(STUDENT_ID),
    CONSTRAINT FK_SC_CLASS FOREIGN KEY (CLASS_ID) REFERENCES CLASSES(CLASS_ID)
);

CREATE TABLE PARENT_STUDENT (
    PARENT_ID NUMBER,
    STUDENT_ID NUMBER,
    RELATION VARCHAR2(50) NOT NULL,
    PRIMARY KEY (PARENT_ID, STUDENT_ID),
    CONSTRAINT FK_PARENT FOREIGN KEY (PARENT_ID) REFERENCES USERS(USER_ID),
    CONSTRAINT FK_STUDENT_PS FOREIGN KEY (STUDENT_ID) REFERENCES STUDENTS(STUDENT_ID)
);

CREATE TABLE QUESTION_PAPERS (
    QP_ID NUMBER PRIMARY KEY,
    CLASS_ID NUMBER NOT NULL,
    SUBJECT_ID NUMBER NOT NULL,
    EXAM_TYPE VARCHAR2(50),
    EXAM_DATE DATE NOT NULL,
    MAX_MARKS NUMBER NOT NULL,
    EXAM_DESCRIPTION VARCHAR2(500),
    CREATED_BY_TEACHER_ID NUMBER,
    CONSTRAINT UQ_QP_CLASS_SUBJECT_DATE UNIQUE (CLASS_ID, SUBJECT_ID, EXAM_DATE),
    CONSTRAINT CHK_QP_MAX_MARKS CHECK (MAX_MARKS > 0),
    CONSTRAINT FK_QP_CLASS FOREIGN KEY (CLASS_ID) REFERENCES CLASSES(CLASS_ID),
    CONSTRAINT FK_QP_SUBJECT FOREIGN KEY (SUBJECT_ID) REFERENCES SUBJECTS(SUBJECT_ID),
    CONSTRAINT FK_QP_CREATED_BY FOREIGN KEY (CREATED_BY_TEACHER_ID) REFERENCES TEACHERS(TEACHER_ID)
);

CREATE TABLE QUESTION_BANK (
    QUESTION_ID NUMBER PRIMARY KEY,
    CLASS_ID NUMBER NOT NULL,
    SUBJECT_ID NUMBER NOT NULL,
    TEACHER_ID NUMBER,
    TITLE VARCHAR2(200) NOT NULL,
    ACADEMIC_YEAR VARCHAR2(10) NOT NULL,
    ORIGINAL_FILE_NAME VARCHAR2(255),
    UPLOADED_AT DATE DEFAULT SYSDATE,
    CONSTRAINT FK_QB_CLASS FOREIGN KEY (CLASS_ID) REFERENCES CLASSES(CLASS_ID),
    CONSTRAINT FK_QB_SUBJECT FOREIGN KEY (SUBJECT_ID) REFERENCES SUBJECTS(SUBJECT_ID),
    CONSTRAINT FK_QB_TEACHER FOREIGN KEY (TEACHER_ID) REFERENCES TEACHERS(TEACHER_ID)
);

CREATE TABLE ASSIGNMENTS (
    ASSIGNMENT_ID NUMBER PRIMARY KEY,
    CLASS_ID NUMBER,
    SUBJECT_ID NUMBER,
    TITLE VARCHAR2(200) NOT NULL,
    DESCRIPTION VARCHAR2(500),
    DUE_DATE DATE NOT NULL,
    CONSTRAINT FK_ASSIGN_CLASS FOREIGN KEY (CLASS_ID) REFERENCES CLASSES(CLASS_ID),
    CONSTRAINT FK_ASSIGN_SUBJECT FOREIGN KEY (SUBJECT_ID) REFERENCES SUBJECTS(SUBJECT_ID)
);

CREATE TABLE MARKS (
    MARK_ID NUMBER PRIMARY KEY,
    STUDENT_ID NUMBER NOT NULL,
    QP_ID NUMBER NOT NULL,
    MARKS_OBTAINED NUMBER CHECK (MARKS_OBTAINED >= 0),
    CONSTRAINT UQ_MARKS UNIQUE (STUDENT_ID, QP_ID),
    CONSTRAINT FK_MARKS_STUDENT FOREIGN KEY (STUDENT_ID) REFERENCES STUDENTS(STUDENT_ID),
    CONSTRAINT FK_MARKS_QP FOREIGN KEY (QP_ID) REFERENCES QUESTION_PAPERS(QP_ID)
);

CREATE TABLE SUBMISSIONS (
    SUBMISSION_ID NUMBER PRIMARY KEY,
    ASSIGNMENT_ID NUMBER,
    STUDENT_ID NUMBER,
    SUBMITTED_ON DATE,
    MARKS NUMBER CHECK (MARKS >= 0),
    CONSTRAINT UQ_SUBMISSION UNIQUE (ASSIGNMENT_ID, STUDENT_ID),
    CONSTRAINT FK_SUB_ASSIGN FOREIGN KEY (ASSIGNMENT_ID) REFERENCES ASSIGNMENTS(ASSIGNMENT_ID),
    CONSTRAINT FK_SUB_STUDENT FOREIGN KEY (STUDENT_ID) REFERENCES STUDENTS(STUDENT_ID)
);

CREATE TABLE ATTENDANCE (
    ATTENDANCE_ID NUMBER PRIMARY KEY,
    USER_ID NUMBER NOT NULL,
    CLASS_ID NUMBER,
    ATTENDANCE_DATE DATE NOT NULL,
    SESSION_TYPE VARCHAR2(2) NOT NULL,
    STATUS VARCHAR2(10) NOT NULL,
    LEAVE_REASON VARCHAR2(200),
    APPROVAL_STATUS VARCHAR2(10),
    APPROVED_BY NUMBER,
    CONSTRAINT UQ_ATTENDANCE UNIQUE (USER_ID, CLASS_ID, ATTENDANCE_DATE, SESSION_TYPE),
    CONSTRAINT CHK_SESSION CHECK (SESSION_TYPE IN ('FN','AN')),
    CONSTRAINT CHK_STATUS CHECK (STATUS IN ('Present','Absent','Leave')),
    CONSTRAINT CHK_APPROVAL CHECK (APPROVAL_STATUS IN ('Pending','Approved','Rejected')),
    CONSTRAINT FK_ATT_USER FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID),
    CONSTRAINT FK_ATT_CLASS FOREIGN KEY (CLASS_ID) REFERENCES CLASSES(CLASS_ID),
    CONSTRAINT FK_ATT_APPROVER FOREIGN KEY (APPROVED_BY) REFERENCES USERS(USER_ID)
);

CREATE TABLE COUNSELLING (
    SESSION_ID NUMBER PRIMARY KEY,
    STUDENT_ID NUMBER,
    COUNSELLOR_ID NUMBER,
    SESSION_DATE DATE,
    NOTES VARCHAR2(500),
    STATUS VARCHAR2(15) DEFAULT 'Pending' NOT NULL,
    CATEGORY VARCHAR2(20) DEFAULT 'Academic' NOT NULL,
    CONSTRAINT CHK_COUNSELLING_STATUS CHECK (STATUS IN ('Pending','Scheduled','Completed')),
    CONSTRAINT CHK_COUNSELLING_CATEGORY CHECK (CATEGORY IN ('Academic','Personal','Career')),
    CONSTRAINT FK_COUN_STUDENT FOREIGN KEY (STUDENT_ID) REFERENCES STUDENTS(STUDENT_ID),
    CONSTRAINT FK_COUN_USER FOREIGN KEY (COUNSELLOR_ID) REFERENCES USERS(USER_ID)
);

CREATE TABLE COMMUNICATION (
    MESSAGE_ID NUMBER PRIMARY KEY,
    SENDER_ID NUMBER REFERENCES USERS(USER_ID),
    RECEIVER_ID NUMBER REFERENCES USERS(USER_ID),
    STUDENT_ID NUMBER REFERENCES STUDENTS(STUDENT_ID),
    MESSAGE_TEXT VARCHAR2(1000) NOT NULL,
    SENT_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IDX_COMM_PARTNERS ON COMMUNICATION(SENDER_ID, RECEIVER_ID);

CREATE TABLE COMMUNICATION_READ_STATE (
    VIEWER_ID NUMBER NOT NULL,
    PARTNER_ID NUMBER NOT NULL,
    STUDENT_ID NUMBER NOT NULL,
    LAST_SEEN_MESSAGE_ID NUMBER DEFAULT 0 NOT NULL,
    LAST_SEEN_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT PK_COMM_READ_STATE PRIMARY KEY (VIEWER_ID, PARTNER_ID, STUDENT_ID),
    CONSTRAINT FK_COMM_READ_VIEWER FOREIGN KEY (VIEWER_ID) REFERENCES USERS(USER_ID),
    CONSTRAINT FK_COMM_READ_PARTNER FOREIGN KEY (PARTNER_ID) REFERENCES USERS(USER_ID),
    CONSTRAINT FK_COMM_READ_STUDENT FOREIGN KEY (STUDENT_ID) REFERENCES STUDENTS(STUDENT_ID),
    CONSTRAINT CHK_COMM_READ_LAST_ID CHECK (LAST_SEEN_MESSAGE_ID >= 0)
);

CREATE INDEX IDX_COMM_READ_VIEWER ON COMMUNICATION_READ_STATE(VIEWER_ID);

CREATE TABLE LOGIN_AUDIT (
    LOG_ID NUMBER PRIMARY KEY,
    USER_ID NUMBER,
    LOGIN_TIME DATE DEFAULT SYSDATE,
    LOGOUT_TIME DATE,
    IP_ADDRESS VARCHAR2(50),
    CONSTRAINT CHK_LOGOUT CHECK (LOGOUT_TIME IS NULL OR LOGOUT_TIME >= LOGIN_TIME),
    CONSTRAINT FK_LOG_USER FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID)
);

CREATE TABLE APP_SETTINGS (
    SETTING_KEY VARCHAR2(50) PRIMARY KEY,
    SETTING_VALUE VARCHAR2(500)
);

CREATE TABLE USER_PROFILE_IMAGES (
    USER_ID NUMBER PRIMARY KEY,
    IMAGE_DATA BLOB NOT NULL,
    MIME_TYPE VARCHAR2(80),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT FK_PROFILE_IMAGE_USER FOREIGN KEY (USER_ID)
        REFERENCES USERS(USER_ID) ON DELETE CASCADE
);

CREATE TABLE SCHOOL_PROFILE_IMAGES (
    IMAGE_ID NUMBER PRIMARY KEY,
    IMAGE_DATA BLOB NOT NULL,
    MIME_TYPE VARCHAR2(80),
    UPDATED_AT DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT CHK_SCHOOL_PROFILE_IMAGE_ID CHECK (IMAGE_ID = 1)
);

-- ========================================
-- LIMIT GUARD TRIGGERS
-- ========================================

CREATE OR REPLACE TRIGGER TRG_CST_MAX_TEACHERS
AFTER INSERT OR UPDATE ON CLASS_SUBJECT_TEACHER
DECLARE
    v_violation_count NUMBER;
BEGIN
    SELECT COUNT(*)
    INTO v_violation_count
    FROM (
        SELECT CLASS_ID
        FROM CLASS_SUBJECT_TEACHER
        GROUP BY CLASS_ID
        HAVING COUNT(DISTINCT TEACHER_ID) > 2
    );

    IF v_violation_count > 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'A class can have only up to 2 teachers.');
    END IF;
END;
/

CREATE OR REPLACE TRIGGER TRG_STUDENT_CLASS_MAX_60
AFTER INSERT OR UPDATE ON STUDENT_CLASS
DECLARE
    v_violation_count NUMBER;
BEGIN
    SELECT COUNT(*)
    INTO v_violation_count
    FROM (
        SELECT CLASS_ID
        FROM STUDENT_CLASS
        GROUP BY CLASS_ID
        HAVING COUNT(DISTINCT STUDENT_ID) > 60
    );

    IF v_violation_count > 0 THEN
        RAISE_APPLICATION_ERROR(-20002, 'A class can have only up to 60 students.');
    END IF;
END;
/

